/** Drive one department's attempts until it certifies, blocks, or runs out of rounds. */
private async driveDepartment(run: ProgramRun, state: DepartmentState, agent: Agent, workspace: string): Promise<void> {
  const current = this.ctx.goals.get(agent)
  if (current === undefined) {
    await this.transition(run, state, 'failed', 'the department session carries no goal')
    return
  }
  if (current.phase === 'blocked') {
    await this.transition(run, state, 'blocked', current.blockedReason?.code)
    return
  }
  if (current.activation === 'disarmed' && current.phase !== 'complete') {
    // A department resumed from persistence starts disarmed; the resume edge
    // is what puts it back under this process's authority.
    this.ctx.goals.resume(agent, { id: current.id, revision: current.revision })
    this.ctx.goals.disarm(agent)
  }

